-- ========================================================
-- Chronicle CMS Database (Independent Schema: chronicle_db)
-- Character Set: utf8mb4 / utf8mb4_unicode_ci
-- ========================================================

CREATE DATABASE IF NOT EXISTS `chronicle_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `chronicle_db`;

-- Drop old tables if re-importing
DROP TABLE IF EXISTS `discussions`;
DROP TABLE IF EXISTS `publications`;
DROP TABLE IF EXISTS `rubrics`;
DROP TABLE IF EXISTS `accounts`;

-- --------------------------------------------------------
-- 1. Table structure for `rubrics` (Taxonomy / Categories)
-- --------------------------------------------------------
CREATE TABLE `rubrics` (
  `rubric_id` int(11) NOT NULL AUTO_INCREMENT,
  `rubric_label` varchar(100) NOT NULL,
  `rubric_slug` varchar(100) NOT NULL,
  `rubric_summary` varchar(255) DEFAULT '',
  PRIMARY KEY (`rubric_id`),
  UNIQUE KEY `idx_rubric_label` (`rubric_label`),
  UNIQUE KEY `idx_rubric_slug` (`rubric_slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Seed data for `rubrics`
INSERT INTO `rubrics` (`rubric_id`, `rubric_label`, `rubric_slug`, `rubric_summary`) VALUES
