-- --------------------------------------------------------
-- 2. Table structure for `accounts` (User / Admin Profiles)
-- --------------------------------------------------------
CREATE TABLE `accounts` (
  `account_id` int(11) NOT NULL AUTO_INCREMENT,
  `full_name` varchar(120) NOT NULL,
  `email_address` varchar(100) NOT NULL,
  `pass_hash` varchar(255) NOT NULL,
  `access_role` varchar(30) NOT NULL DEFAULT 'user',
  `occupation_title` varchar(100) DEFAULT '',
  `auth_handle` varchar(50) DEFAULT '',
  `created_timestamp` datetime DEFAULT CURRENT_TIMESTAMP,
  `plain_backup` varchar(255) DEFAULT '',
  PRIMARY KEY (`account_id`),
  UNIQUE KEY `idx_email_address` (`email_address`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Seed data for `accounts` (Admin & Regular User)
