-- --------------------------------------------------------
-- 3. Table structure for `publications` (Articles / News)
-- --------------------------------------------------------
CREATE TABLE `publications` (
  `pub_id` int(11) NOT NULL AUTO_INCREMENT,
  `headline` varchar(255) NOT NULL,
  `content_body` mediumtext NOT NULL,
  `cover_binary` longblob NOT NULL,
  `rubric_ref_id` int(11) NOT NULL,
  `author_ref_id` int(11) NOT NULL,
  `published_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `view_counter` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`pub_id`),
  KEY `idx_pub_rubric` (`rubric_ref_id`),
  KEY `idx_pub_author` (`author_ref_id`),
  CONSTRAINT `fk_pub_rubric` FOREIGN KEY (`rubric_ref_id`) REFERENCES `rubrics` (`rubric_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pub_author` FOREIGN KEY (`author_ref_id`) REFERENCES `accounts` (`account_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Seed data for `publications` (with high quality photos)
INSERT INTO `publications` (`pub_id`, `headline`, `content_body`, `cover_binary`, `rubric_ref_id`, `author_ref_id`, `published_at`) VALUES
(1, 'Autonomous AI Agents Transforming Global Software Engineering', 'Autonomous artificial intelligence agents are reshaping modern software development workflows worldwide. Industry reports indicate that AI-assisted pair programming and self-healing deployment pipelines have increased developer velocity by over 40% this quarter. Engineering teams are leveraging deep code intelligence to automate verification, optimize database queries, and accelerate feature shipping safely.', , 1, 1, NOW() - INTERVAL 5 DAY),
(2, 'Clean Energy Breakthrough: Fusion Reactor Sustains Net Power Output', 'Physicists and energy researchers have announced a milestone in magnetic confinement fusion. The experimental reactor sustained continuous net positive power output across multiple cycles, marking a transformative leap towards limitless, carbon-free energy for industrial power grids. Global investments in clean fusion tech continue to soar.', , 3, 1, NOW() - INTERVAL 4 DAY),
(3, 'Next-Generation Space Telescope Reveals Exoplanet Atmospheric Spectra', 'Astronomers utilizing newly deployed deep space orbital observatories have captured detailed atmospheric composition signatures of habitable-zone exoplanets. The discovery offers unprecedented insights into terrestrial planet formation and potential biosignature detection beyond our solar system.', , 3, 1, NOW() - INTERVAL 3 DAY),
(4, 'Global Financial Markets Embrace Decentralized Settlement Protocols', 'Major international banking consortiums and financial authorities have begun deploying next-generation settlement protocols. The transition significantly minimizes cross-border transaction delays while enhancing cryptographic security and auditability across liquidity networks.', , 4, 1, NOW() - INTERVAL 2 DAY),
(5, 'World Athletics Championship Concludes with Historic Record Times', 'The 2026 World Athletics Championship concluded this weekend with athletes setting historic records across track and field events. Spectacular performances drew global audiences, setting new benchmarks in athletic endurance and modern sports science preparation.', , 5, 1, NOW() - INTERVAL 1 DAY);

-- --------------------------------------------------------
-- 4. Table structure for `discussions` (User Comments)
-- --------------------------------------------------------
CREATE TABLE `discussions` (
  `discussion_id` int(11) NOT NULL AUTO_INCREMENT,
  `author_ref_id` int(11) DEFAULT 1,
  `pub_ref_id` int(11) NOT NULL,
  `commentary` varchar(600) NOT NULL,
  `posted_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `is_approved` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`discussion_id`),
  KEY `idx_disc_pub` (`pub_ref_id`),
  KEY `idx_disc_author` (`author_ref_id`),
  CONSTRAINT `fk_disc_pub` FOREIGN KEY (`pub_ref_id`) REFERENCES `publications` (`pub_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_disc_author` FOREIGN KEY (`author_ref_id`) REFERENCES `accounts` (`account_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

